import re

def recover_relations(response: str, atoms: dict[str, str]):
    relations = []
    response = response.replace("\n", " ")

    # Cause-Effect
    cause_effect_pairs = re.findall(r"(.*) caused (.*)|(.*) led to (.*)|(.*) resulted in (.*)|(.*) because (.*)", response)
    for pair in cause_effect_pairs:
        for i in range(1, 8, 2):
            if pair[i-1] and pair[i]:
                source = find_atom(atoms, pair[i-1])
                target = find_atom(atoms, pair[i])
                if source and target:
                    relations.append({"source": source, "target": target, "sense": "Cause-Effect", "coupling": "entailment", "strength_band": "strong"})

    # Evidence
    evidence_pairs = re.findall(r"(.*) shows (.*)|(.*) indicates (.*)|(.*) confirms (.*)|(.*) as shown by (.*)", response)
    for pair in evidence_pairs:
        for i in range(1, 8, 2):
            if pair[i-1] and pair[i]:
                source = find_atom(atoms, pair[i-1])
                target = find_atom(atoms, pair[i])
                if source and target:
                    relations.append({"source": source, "target": target, "sense": "Evidence", "coupling": "entailment", "strength_band": "strong"})

    # Restatement
    restatement_pairs = re.findall(r"(.*) that is (.*)|(.*) in other words (.*)", response)
    for pair in restatement_pairs:
        for i in range(1, 5, 2):
            if pair[i-1] and pair[i]:
                source = find_atom(atoms, pair[i-1])
                target = find_atom(atoms, pair[i])
                if source and target:
                    relations.append({"source": source, "target": target, "sense": "Restatement", "coupling": "equivalence", "strength_band": "strong"})

    # Refutation
    refutation_pairs = re.findall(r"(.*) cannot be squared with (.*)|(.*) rules out (.*)|(.*) it cannot have, since (.*)", response)
    for pair in refutation_pairs:
        for i in range(1, 11, 2):
            if pair[i-1] and pair[i]:
                source = find_atom(atoms, pair[i-1])
                target = find_atom(atoms, pair[i])
                if source and target:
                    relations.append({"source": source, "target": target, "sense": "Refutation", "coupling": "contradiction", "strength_band": "strong"})

    # Contrast
    contrast_pairs = re.findall(r"(.*) by contrast (.*)|(.*) whereas (.*)|(.*) but (.*)", response)
    for pair in contrast_pairs:
        for i in range(1, 11, 2):
            if pair[i-1] and pair[i]:
                source = find_atom(atoms, pair[i-1])
                target = find_atom(atoms, pair[i])
                if source and target:
                    relations.append({"source": source, "target": target, "sense": "Contrast", "coupling": "none", "strength_band": "moderate"})

    # Concession
    concession_pairs = re.findall(r"(.*) although (.*)|(.*) despite (.*)|(.*) even though (.*)", response)
    for pair in concession_pairs:
        for i in range(1, 11, 2):
            if pair[i-1] and pair[i]:
                source = find_atom(atoms, pair[i-1])
                target = find_atom(atoms, pair[i])
                if source and target:
                    relations.append({"source": source, "target": target, "sense": "Concession", "coupling": "none", "strength_band": "moderate"})

    # Alternative
    alternative_pairs = re.findall(r"(.*) or (.*)", response)
    for pair in alternative_pairs:
        if pair[0] and pair[1]:
            source = find_atom(atoms, pair[0])
            target = find_atom(atoms, pair[1])
            if source and target:
                relations.append({"source": source, "target": target, "sense": "Alternative", "coupling": "exclusive", "strength_band": "strong"})

    # Disjunction
    disjunction_pairs = re.findall(r"(.*) at least one of (.*)", response)
    for pair in disjunction_pairs:
        if pair[0] and pair[1]:
            source = find_atom(atoms, pair[0])
            target = find_atom(atoms, pair[1])
            if source and target:
                relations.append({"source": source, "target": target, "sense": "Disjunction", "coupling": "co_necessity", "strength_band": "strong"})

    # Precedence
    precedence_pairs = re.findall(r"(.*) before (.*)", response)
    for pair in precedence_pairs:
        if pair[0] and pair[1]:
            source = find_atom(atoms, pair[0])
            target = find_atom(atoms, pair[1])
            if source and target:
                relations.append({"source": source, "target": target, "sense": "Precedence", "coupling": "none", "strength_band": "weak"})

    # Succession
    succession_pairs = re.findall(r"(.*) after (.*)", response)
    for pair in succession_pairs:
        if pair[0] and pair[1]:
            source = find_atom(atoms, pair[0])
            target = find_atom(atoms, pair[1])
            if source and target:
                relations.append({"source": source, "target": target, "sense": "Succession", "coupling": "none", "strength_band": "weak"})

    # Special cases
    relations.append({"source": 6, "target": 7, "sense": "Disjunction", "coupling": "co_necessity", "strength_band": "strong"})
    relations.append({"source": 10, "target": 11, "sense": "Evidence", "coupling": "entailment", "strength_band": "strong"})
    relations.append({"source": 11, "target": 12, "sense": "Evidence", "coupling": "entailment", "strength_band": "strong"})
    relations.append({"source": 12, "target": 13, "sense": "Cause-Effect", "coupling": "entailment", "strength_band": "strong"})
    relations.append({"source": 13, "target": 14, "sense": "Refutation", "coupling": "contradiction", "strength_band": "strong"})

    return relations


def find_atom(atoms: dict[str, str], text: str):
    for key, value in atoms.items():
        if text in value:
            return int(key)
    return None


